import json,re
from pathlib import Path
P=Path(__file__).parent
D={k:[] for k in ['grapes','translations','existingUpdates','regions','wines','evidence','unresolved','corrections']}
def B(s):
 a=s.split('|',1);return {'en':a[0],'zh':a[-1]}
def save():
 (P/'central.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n');print('checkpoint',len(D['grapes']),len(D['regions']),sum(len(r['questions']) for r in D['regions']))
V='https://www.vivairauscedo.com/scheda-prodotto/'
L='https://www.arsial.it/wp-content/uploads/2025/06/Volume_Vitigni_2026_WEB.pdf'
LW='https://www.arsial.it/wp-content/uploads/2026/04/Volume-Vini-2026.pdf'
M='https://www.consorziomontefalco.it/wp-content/uploads/2024/06/Booklet-Istituzionale-Consorzio-Tutela-Vini-Montefalco_2024.pdf'
GREG={}
def grape(id,name,color,admin,origin,summary,vit,vin,taste,similar,aliases='',urls=None,parents=None,extra=None):
 urls=urls or [V+id+'/'];pairs=[B(x) for x in [origin,summary,vit,vin,taste,similar]]
 g={'id':id,'name':name,'zh':name,'color':color,'countries':['Italy'],'aliases':[],'regions':[{'name':admin,'country':'Italy','note':B(origin)['zh']}],'sources':[{'title':('ARSIAL — Lazio grape varieties' if u==L else 'Primary variety or production reference')+' · '+name,'url':u} for u in urls],'reviewed':'2026-10-26','editorialBatch':'expansion-italy-central'}
 en={'id':id,'species':'Vitis vinifera','originCountry':'Italy','aliases':[],'regions':[{'name':admin,'note':B(origin)['en']}]}
 for key,pair in zip(['origin','summary','viticulture','winemaking','taste','confusions'],pairs):g[key]=pair['zh'];en[key]=pair['en']
 for a in aliases.split(';;'):
  if a:
   n,ctx=a.split('~',1);p=B(ctx);g['aliases'].append({'name':n,'context':p['zh']});en['aliases'].append({'name':n,'context':p['en']})
 note=B('Complete parentage not established in the sources reviewed.|本次核查的来源未确定完整双亲。') if not parents else B(parents[2])
 g['genetics']={'type':parents[0] if parents else 'unknown','parents':parents[1] if parents else [],'note':note['zh']};en['geneticsNote']=note['en']
 g['referenceRows']=[]
 # Detailed rows contain positive source facts; unknown parentage is kept in its dedicated field.
 for sec,lab,idx in [('origin','Origin|起源',0),('viticulture','Viticulture|栽培',2),('vinification','Vinification|酿造',3),('tasting','Structure and aroma|结构与香气',4)]:g['referenceRows'].append({'section':sec,'label':B(lab),'text':pairs[idx],'sourceUrls':[urls[0]]})
 if extra:
  for sec,lab,txt,ui in extra:g['referenceRows'].append({'section':sec,'label':B(lab),'text':B(txt),'sourceUrls':[urls[ui]]})
 D['grapes'].append(g);D['translations'].append(en);GREG[id]=admin
 return g

grape('pecorino','Pecorino','white','Marche','Historically cultivated in Marche and the central Adriatic; Arquata del Tronto is a reference locality.|历史栽培集中于 Marche 与亚得里亚海中部，Arquata del Tronto 是重要地点。','Early ripening with high acidity and substantial structure; central to varietal Offida whites.|早熟而酸度高、结构扎实；是 Offida 单品种白酒的重要葡萄。','Medium budbreak; early maturity. Medium-low vigour, moderate and sometimes irregular yields; suits warm-temperate sites and slightly calcareous clay.|萌芽中等、成熟早；生长势中低，产量中等且有波动；适合温暖温带及微钙质黏土。','Still, sparkling and ageworthy white styles; VCR417 can support barrel maturation.|适合静态、起泡及可陈年白酒；VCR417 可用于桶陈。','High acidity, firm structure, fresh fruit and spice; VCR417 shows apple and flowers.|酸度高，结构坚实，鲜果及香料；VCR417 呈苹果与花香。','Compared with Passerina, typically earlier ripening and less productive; the contrast is viticultural, not a synonym relationship.|与 Passerina 相比通常成熟更早、产量较低；二者是栽培特征对照，并非异名。',extra=[('viticulture','Berries|果粒','Small to medium berries with thin skin of medium consistency.|果粒中小，果皮薄而质地中等。',0),('viticulture','Training|整形修剪','Medium-long pruning is preferred; spur cordon is possible, particularly with VCR417.|偏好中长梢修剪，尤其 VCR417 也可采用短梢水平主干。',0)])
grape('passerina','Passerina','white','Marche','A central Adriatic variety of uncertain precise origin, cultivated in Marche and Abruzzo.|亚得里亚海中部品种，确切起源未定，在 Marche 与 Abruzzo 栽培。','A vigorous late-ripening white grape serving both varietal still wines and sparkling production.|生长势强、成熟晚，可用于单酿静态及起泡白酒。','Mid-late budbreak and late ripening; high, consistent production. Large bunches and berries with thick, resistant skins.|萌芽中晚、成熟晚；高产且稳定，果串和果粒大、皮厚坚韧。','Long, generous pruning suits its vigour; VCR6 is used for sparkling and blended still wines.|适合较长且留芽量多的修剪；VCR6 可酿起泡及混酿静态酒。','Generally full and dry with useful acidity; clone expression varies from herbal to fruit and spice.|通常干型、口感充实且酸度良好；克隆表现可由草本至果香与香料。','Its bunches resemble Trebbiano Toscano morphologically; that observation does not establish genetic identity.|果串形态与 Trebbiano Toscano 相近，但形态相似不能确定遗传同一性。',extra=[('viticulture','Spring frost|春霜','Mid-late budbreak reduces exposure to early spring cold.|中晚萌芽降低早春低温暴露。',0),('tasting','Clonal variation|克隆差异','VCR450 has more golden colour, fruit-spice notes and a bitter finish; VCR6 emphasizes acidity.|VCR450 偏金黄色、果香与香料并带微苦收尾；VCR6 更突出酸度。',0)])
grape('grechetto','Grechetto di Orvieto','white','Umbria','Central Italian variety associated with Orvieto; this dossier follows the Orvieto identity.|意大利中部与 Orvieto 紧密相连的品种，本档案专指 Orvieto 类型。','White grape for varietal wines and blends, bringing acidity and apple-pear fruit.|可单酿或混酿，为酒体提供酸度及苹果、梨风味。','Medium budbreak, maturity, vigour and consistent yields; compact bunches. Suits heavier hill soils, including mildly calcareous sites.|萌芽、成熟、生长势均中等，产量稳定；果串紧密，适合较重的丘陵土壤，包括轻钙质地。','Medium-long pruning; fruit can be vinified alone or blended for aromatic finesse.|宜中长梢修剪，可单酿或混酿以增加细致果香。','Good acidity, delicate apple and pear aromas, often greenish yellow colour.|酸度良好、苹果梨香细致，常呈带绿调的黄色。','Grechetto Gentile / Grechetto di Todi is Pignoletto. The unqualified word Grechetto can be ambiguous.|Grechetto Gentile／Grechetto di Todi 是 Pignoletto；裸词 Grechetto 存在歧义。','Grechetto~Orvieto identity only; unqualified usage is ambiguous.|限 Orvieto 身份；裸词用法含混。',urls=[V+'grechetto/'],extra=[('viticulture','Disease|病害','Susceptible to Botrytis; less sensitive to downy and powdery mildew in the VCR description.|VCR 描述其易受灰霉影响，对霜霉及白粉病相对较不敏感。',0),('similar','Identity|身份','The VCR sheet explicitly separates Orvieto from the Todi/Pignoletto identity.|VCR 技术资料明确区分 Orvieto 与 Todi／Pignoletto 身份。',0)])
grape('maceratino','Maceratino','white','Marche','Centred on Macerata, with cultivation in adjoining Ancona and Ascoli Piceno.|集中于 Macerata，也见于邻近 Ancona 和 Ascoli Piceno。','The local white grape known as Ribona, important in Colli Maceratesi.|当地称 Ribona，是 Colli Maceratesi 的重要白葡萄。','Mid-late budbreak and ripening; vigorous, high and regular yielding, with compact bunches.|萌芽与成熟中晚，生长势强、高产稳定，果串紧密。','Suitable for white-wine production; good acidity and floral character support local varietal expressions.|用于白葡萄酒，良好酸度及花香支持当地单品种风格。','Floral, citrus and fresh-fruit tones; VCR481 also records aromatic-herb notes.|花香、柑橘及鲜果；VCR481 另有芳香草本。','Ribona names this grape; historical Greek-origin suggestions are not proof of parentage.|Ribona 是其名称；历史希腊起源说法不能充当亲缘证明。','Ribona~Local Marche synonym.|Marche 地方异名。',extra=[('viticulture','Sensitivity|敏感性','Limited cold resistance; susceptible to downy and powdery mildew.|抗寒能力较弱，对霜霉及白粉病敏感。',0),('viticulture','Adaptation|适应性','Adapted to temperate Marche coastal conditions, including relatively infertile soils.|适应 Marche 沿海温带条件，也可种于较贫瘠土壤。',0)])
grape('foglia-tonda','Foglia Tonda','red','Toscana','Old Tuscan grape rediscovered in Chianti vineyards.|托斯卡纳古老品种，在 Chianti 葡萄园重新受到关注。','A local blending grape adding substance and ageing potential to Tuscan reds.|为托斯卡纳红酒混酿增加厚度及陈年潜力。','Medium vigour and productivity; medium to large pyramidal, semi-compact to compact bunches.|中等生长势及产量；果串中大、金字塔形，半紧密至紧密。','Traditionally blended with other Chianti varieties to reinforce structure.|传统上与 Chianti 其他品种混酿，以强化结构。','Neutral berry flavour; wines contribute body and robustness rather than Muscat-like perfume.|果肉风味中性；主要贡献酒体和结构。','Its rounded, weakly lobed leaf is a useful ampelographic character, not a parentage statement.|圆形且浅裂的叶片是形态识别特征，并非亲缘结论。',extra=[('viticulture','Leaf|叶片','Orbicular, medium-sized leaves, entire or only slightly lobed.|叶片中等、近圆形，全缘或仅浅裂。',0),('viticulture','Berry|果粒','Medium slightly obovoid berries; blue, heavily bloomed skins.|果粒中等、微倒卵形；蓝色果皮且果粉浓厚。',0)])
grape('pugnitello','Pugnitello','red','Toscana','Old Tuscan black grape of uncertain exact origin.|托斯卡纳古老黑葡萄，确切起源未定。','A deeply coloured red variety combining alcohol, acidity and fine tannin.|深色红葡萄，可兼具酒精度、酸度及细致单宁。','Small, short, fist-like pyramidal bunches; medium berries with thick, leathery blue-black skins.|果串小短、形似拳头；果粒中等，蓝黑果皮厚且坚韧。','Its concentrated phenolic material supports substantial red wines; extraction should follow fruit maturity.|浓缩酚类物质支持结构型红酒；萃取程度需依据果实成熟度。','Intense ruby-violet colour, slight herbaceousness, full palate, good acidity and fine tannins.|浓郁宝石红带紫调，轻微草本，口感充实、酸度良好、单宁细致。','The small bunch explains the name; it does not establish a relationship with other similarly shaped grapes.|小果串解释其名称，不能据此认定与其他相似葡萄的亲缘。',extra=[('viticulture','Pulp|果肉','Colourless, juicy and firm pulp; VCR records herbaceous and pepper-like berry flavours.|果肉无色、多汁而结实；VCR 记录草本及椒类果实风味。',0),('viticulture','Leaf|叶片','Medium pentagonal, five-lobed leaf with a closed petiolar sinus.|中等五角形、五裂叶片，叶柄窦闭合。',0)])
grape('malvasia-del-lazio','Malvasia del Lazio','white','Lazio','Long cultivated in the hills of Lazio; an eastern Mediterranean origin is traditional rather than demonstrated.|长期栽培于 Lazio 丘陵；东地中海起源属于传统推测。','Also called Malvasia Puntinata; a key Frascati blending grape with aromatic delicacy and body.|亦称 Malvasia Puntinata，是 Frascati 重要混酿品种，贡献细致香气及酒体。','Late budbreak, mid-late maturity; moderate vigour and sometimes irregular yields. Prefers well-exposed hills.|萌芽晚、成熟中晚；生长势中等、产量有时不稳，偏好向阳丘陵。','Frequently blended with Trebbiani and other Malvasias; also made as a varietal white.|常与 Trebbiano 类及其他 Malvasia 混酿，也可单酿。','Pale straw, mildly aromatic, rounded and moderately alcoholic, with savoury persistence.|浅稻草色、微芳香、口感圆润，酒精度适中而余味鲜美。','Malvasia Bianca di Candia is a separate variety used alongside it in Frascati.|Malvasia Bianca di Candia 是另一品种，在 Frascati 与其共同使用。','Malvasia Puntinata~Established Lazio name.|Lazio 常用名称。',urls=[V+'malvasia-del-lazio/',LW],extra=[('viticulture','Bunch|果串','Medium-large, truncated conical and winged; berries have firm skins.|果串中大、截锥形且带翼，果皮坚实。',0),('vinification','Frascati role|Frascati 角色','Frascati rules group it with Malvasia Bianca di Candia for the principal white component.|Frascati 规范将其与 Malvasia Bianca di Candia 合并计入主要白葡萄组。',1)])
save()
# Lazio: contemporary regional ampelographic descriptions; folklore is qualified.
lazio=[
('bellone','Bellone','white','Recorded around Rome in nineteenth-century ampelographies; also called Cacchione.|十九世纪罗马周边葡萄学资料已有记载，亦称 Cacchione。','A productive Lazio white used in Cori, Nettuno, Marino and Roma wines.|Lazio 的高产白葡萄，用于 Cori、Nettuno、Marino 及 Roma 酒。','Vigorous, high and regular yielding; likes deep, fresh volcanic hill soils and medium-long pruning.|生长势强、高产稳定；偏好深厚凉润的火山丘陵土及中长梢修剪。','Makes still whites, with local varietal bottlings and blends.|用于静态白酒，当地有单酿及混酿。','Floral and fruity, rounded, persistent palate.|花果香、口感圆润而余味持久。','Cacchione is a synonym; Pampanaro/Bello must remain separate.|Cacchione 是异名；Pampanaro／Bello 须分开。','Cacchione~Lazio synonym.|Lazio 异名。','Compact bunches are especially susceptible to sour rot.|紧密果串尤其易受酸腐病影响。','Medium-large berries with thick yellowish skins.|果粒中大，果皮厚、偏黄色。'),
('cesanese-comune','Cesanese Comune','red','Documented by Acerbi in 1825 and distinguished from d’Affile by Mengarini in 1888.|Acerbi 于1825年记载；Mengarini 于1888年将其与 d’Affile 区分。','A major historic red of Rome and Frosinone, used in Cesanese denominations.|Roma 与 Frosinone 的历史红葡萄，用于 Cesanese 系列产区。','Moderate vigour, abundant yields; needs exposed hills. Ripening is difficult at elevation or in poor exposures.|生长势中等、产量高，需要向阳丘陵；海拔高或朝向差时成熟困难。','Used for regional reds, including Piglio blends with Cesanese d’Affile.|用于地方红酒，包括 Piglio 与 Cesanese d’Affile 的组合。','Ruby becoming garnet; delicate floral-fruit aromas and a soft, slightly bitter finish.|宝石红陈年转石榴色；细致花果香、柔和而微苦收尾。','Registered as variety 060, separately from Cesanese d’Affile 061.|登记号060，与 Cesanese d’Affile 的061分列。','Cesanese~Designation synonym for Comune; the bare name may also be used generically.|Comune 的标示异名；裸词也可泛指该类名称。','Sensitive to fungal disease, particularly downy mildew; coulure can occur.|对真菌病、尤其霜霉敏感，也可能落花落果。','Medium oval berries with thick blue-violet skins.|果粒中等椭圆，果皮厚、蓝紫色。'),
('cesanese-d-affile','Cesanese d’Affile','red','Distinguished from Comune in 1888; especially associated with Frosinone and Affile.|1888年已与 Comune 区分，尤其与 Frosinone、Affile 有关。','Important quality component of Piglio and Affile reds, often also vinified alone.|Piglio 和 Affile 红酒的重要品种，也常单酿。','Moderate vigour and moderate, sometimes irregular crops; favours exposed hills and medium-short pruning.|生长势中等、产量中等且有波动；偏好向阳丘陵及中短梢修剪。','Still red vinification; authorised alongside Comune in Cesanese del Piglio.|酿静态红酒；在 Cesanese del Piglio 中与 Comune 同列允许品种。','Ruby-purple turning garnet; delicate fragrance and rounded, slightly bitter palate.|宝石红带紫调、陈年转石榴色；香气细致、口感圆润略苦。','Separate catalogue identity 061; do not collapse into Comune on the shared Cesanese name.|独立登记号061，不能因同有 Cesanese 名称而并入 Comune。','','Generally sensitive to fungal diseases.|通常对真菌病敏感。','Its crop is less consistently abundant than the regional description of Comune.|地区资料描述其产量不如 Comune 丰富稳定。'),
('moscato-di-terracina','Moscato di Terracina','white','Long cultivated around Terracina; Mengarini recorded it in 1888 and Zappi Recordati described it in 1927.|长期栽培于 Terracina，1888及1927年已有专门记载。','Dual-purpose aromatic grape and the defining variety of Terracina DOC.|兼具鲜食与酿酒用途的芳香品种，是 Terracina DOC 的核心。','Vigorous, abundant regular crops; exposed calcareous hills and medium-long pruning suit it.|生长势强、丰产稳定；适合向阳钙质丘陵及中长梢修剪。','Dry, off-dry, passito and sparkling versions are made in Terracina.|Terracina 有干型、半甜、风干甜型及起泡版本。','Pronounced Muscat aroma, soft texture, good alcohol and moderate acidity.|麝香葡萄香浓郁，质地柔和，酒精度良好、酸度适中。','Moscatellone/Moscatello are designation names here; do not merge all Muscat names.|Moscatellone／Moscatello 在此为标示名称，不应合并所有 Muscat 名称。','Moscatellone~Local designation synonym.|地方标示异名。;;Moscatello~Local designation synonym.|地方标示异名。','Compact bunches increase rot vulnerability despite good mildew tolerance.|尽管耐霜霉与白粉病良好，紧密果串仍增加腐烂风险。','Registered for wine grapes in 2004 after a long table-grape history.|长期鲜食历史后，于2004年登记为酿酒葡萄。'),
('capolongo','Capolongo','white','Recorded in Valle del Liri in 1878; exact origin unknown.|1878年在 Valle del Liri 有记载，确切起源未知。','Rare southern Lazio white for still and sparkling wines.|Lazio 南部稀有白葡萄，可酿静态及起泡酒。','Moderate vigour and irregular moderate yields; sunny hills and long pruning.|中等生长势及产量，收成波动；宜向阳丘陵、长梢修剪。','White vinification; regional trials indicate sparkling potential.|白葡萄酒酿造，地区试验显示起泡潜力。','Deep straw to golden, floral and fruity, soft palate.|深稻草黄至金色，花果香，口感柔和。','Reale Gialla refers to Capolongo; Reale Bianca is a different registered variety.|Reale Gialla 指 Capolongo；Reale Bianca 为另一登记品种。','Reale Gialla~Esperia local name.|Esperia 地方名称。','Moderate tolerance of downy and powdery mildew.|对霜霉和白粉病有一定耐性。','Medium compact cylindrical bunches, one to three wings, elliptical yellow berries.|中等紧密圆柱果串，带1至3翼，椭圆黄色果粒。'),
('lecinaro','Lecinaro','red','Recorded in Val di Comino and Valle del Liri in 1878.|1878年已记载于 Val di Comino 和 Valle del Liri。','A local Lazio red with plum-shaped berries and floral-fruit expression.|Lazio 地方红葡萄，果粒似李子，具花果香。','Moderate vigour and regular moderate crops; exposed hills and short-medium pruning.|生长势中等、收成稳定适中；宜向阳丘陵及中短梢修剪。','Used for local red-wine production.|用于地方红葡萄酒。','Ruby-violet, fruity and floral, round and balanced.|宝石红带紫色，花果香，圆润平衡。','Lecina is the Sora local name; the plum comparison explains nomenclature rather than ancestry.|Lecina 是 Sora 地方称呼；李子比喻解释名称而非祖源。','Lecina~Sora local name.|Sora 地方名称。','Good tolerance to fungal diseases reported by ARSIAL.|ARSIAL 记录对真菌病耐受良好。','Elongated elliptical berries with thick blue-black skins.|果粒细长椭圆，果皮厚、蓝黑色。'),
('maturano','Maturano','white','Cited in 1859 and described in 1878 from Val di Comino and Valle del Liri.|1859年已有记载，1878年描述其分布于 Val di Comino 和 Valle del Liri。','Southern Lazio white giving fruit-driven wines with useful acidity.|Lazio 南部白葡萄，酒款以果味和良好酸度见长。','Medium vigour, moderate constant yields; sunny hills and medium-short pruning.|中等生长势及稳定适中产量；宜向阳丘陵、中短梢修剪。','Local still whites, including varietal bottlings.|用于地方静态白酒及单品种装瓶。','Intense straw, exotic-fruit aromas, savoury palate and good acid structure.|深稻草黄、热带果香、鲜美口感及良好酸度结构。','Maturano Nero has a separate registration; no colour-mutation relationship is asserted here.|Maturano Nero 独立登记，本条未断言其为颜色突变。','','Generally relatively insensitive to fungal diseases in the regional description.|地区资料描述其一般对真菌病较不敏感。','Medium compact conical bunches and elliptical green-yellow berries.|中等紧密圆锥果串，椭圆绿黄色果粒。'),
('maturano-nero','Maturano Nero','red','Documented in Alvito in 1878, with local records from Sora and Pontecorvo.|1878年记载于 Alvito，亦见 Sora 与 Pontecorvo 记录。','Late-ripening southern Lazio red generally used with other local varieties.|Lazio 南部晚熟红葡萄，通常与当地其他品种混酿。','Moderate vigour and regular yields; late berry maturity, short-medium pruning.|生长势中等、产量稳定，果实成熟晚，适合中短梢修剪。','Usually blended with other local varieties.|通常与其他地方品种混酿。','Pale ruby to onion-skin tones; fruit and flowers, restrained tannin and acidity.|浅宝石红至洋葱皮色；花果香，单宁及酸度较低。','Matrano Nero and Modulano are documented local names; Maturano white is separate.|Matrano Nero 与 Modulano 是有记载的地方名称；白色 Maturano 分开。','Matrano Nero~Sora historical name.|Sora 历史名称。;;Modulano~Pontecorvo historical name.|Pontecorvo 历史名称。','Strong tolerance to adverse conditions and fungal disease reported regionally.|地区资料记录其对不利环境及真菌病耐受力强。','Registered wine-grape number 912.|酿酒葡萄登记号912。'),
('pampanaro','Pampanaro','white','Recorded in southern Lazio in 1878; molecular work identifies it with the Castelli Romani Bello material.|1878年记载于 Lazio 南部；分子研究将其与 Castelli Romani 的 Bello 材料对应。','A productive local white with floral fruit and substantial acidity.|高产地方白葡萄，具花果香及扎实酸度。','Vigorous, adaptable, abundant and regular yields; short-medium pruning.|生长势强、适应广、丰产稳定，适合中短梢修剪。','Used for local white-wine production.|用于地方白葡萄酒。','Chamomile, apple and pear; savoury, harmonious, with good acidity.|洋甘菊、苹果及梨；鲜美协调、酸度良好。','Bello is confirmed here; Bellone remains a distinct entry.|此处确认 Bello 对应关系；Bellone 仍为不同条目。','Bello~Castelli Romani identity supported by molecular investigation.|分子研究支持的 Castelli Romani 名称。','Good downy/powdery mildew tolerance; compact bunches are more vulnerable to rot.|对霜霉与白粉病耐受良好，但紧密果串较易腐烂。','Adapts to compact soils and stony calcareous sites.|可适应较紧实土及多石钙质地。'),
('raspato-nero','Raspato Nero','red','Recorded as Olivella in 1877; now associated especially with Esperia near the Aurunci hills.|1877年以 Olivella 记载，现尤其与 Aurunci 山旁 Esperia 有关。','Local Lazio red commonly vinified alone, combining floral aromas and balanced acidity.|常单酿的 Lazio 地方红葡萄，兼具花香及平衡酸度。','Moderate vigour; prefers fresh, compact calcareous-clay slopes without waterlogging.|生长势中等，偏好凉润、紧实但不积水的钙质黏土坡地。','Usually varietal red vinification.|通常单品种红酒酿造。','Ruby-violet, violet flowers, cherry and berries; good alcohol and balanced acid structure.|宝石红带紫调，紫罗兰、樱桃与浆果；酒精度良好、酸度结构平衡。','Local Olivella di Esperia is qualified geographically; do not merge every Olivella homonym.|Olivella di Esperia 需保留地域限定，不能合并所有同名 Olivella。','Ulivello Nero~Esperia local name.|Esperia 地方名称。;;Olivella di Esperia~Qualified Lazio local name.|带地域限定的 Lazio 地方名称。','Good fungal disease tolerance; short or long pruning with restrained bud load.|真菌病耐受良好；可短或长梢修剪，但留芽量不宜过大。','Elliptical berries with medium-thick skins and firm, relatively low-juice pulp.|果粒椭圆、皮中厚，果肉结实且汁较少。'),
('reale-bianca','Reale Bianca','white','Traditional Esperia grape near the Aurunci hills; precise origin unknown.|Aurunci 山旁 Esperia 的传统葡萄，确切起源未知。','Vigorous local white giving full, relatively low-acid wines.|生长势强的地方白葡萄，酒体较足、酸度较低。','Very vigorous; fresh calcareous-clay sites and expanded training with long pruning.|生长势很强；宜凉润钙质黏土地、较开展的整形及长梢修剪。','Usually vinified as a varietal white.|通常单酿白葡萄酒。','Wildflowers, yellow fruit and pineapple; good alcohol with low acidity.|野花、黄色水果及菠萝，酒精度良好、酸度低。','Not Reale Gialla, the local name for Capolongo.|不同于 Capolongo 的地方名称 Reale Gialla。','','Good reported tolerance to fungal disease and climatic adversity.|资料记录对真菌病及不利气候有良好耐性。','Medium, wingless conical bunches and thick-skinned green-yellow berries.|中等无翼圆锥果串，绿黄果粒且皮厚。'),
('rosciola','Rosciola','pink','Recorded near Cassino in 1878; surviving cultivation described in the upper Aniene valley.|1878年记载于 Cassino 附近，现有栽培记录集中在 Aniene 上游。','Pink-skinned dual-purpose grape with strong potential for sparkling rosé.|粉红果皮、鲜食酿酒兼用，适合起泡桃红。','Vigorous, regular abundant yields; sunny calcareous hills and short pruning.|生长势强、丰产稳定；宜向阳钙质丘陵及短梢修剪。','Rosé and sparkling vinification; also used as a table grape.|可酿桃红及起泡酒，也可鲜食。','Pink colour, little tannin and high acidity with a soft texture.|粉红色、低单宁、高酸度，同时质地柔和。','This dossier is the registered Lazio Rosciola, catalogue 429; pink colour alone does not identify other Rosciola names.|本条为登记号429的 Lazio Rosciola，粉红果皮不足以确认其他同名材料。','','Grapes can remain well preserved on the vine.|葡萄在藤上保持状态的能力较好。','Good fungal disease tolerance is reported by the regional institute.|地区机构记录其对真菌病耐受良好。'),
('trebbiano-giallo','Trebbiano Giallo','white','Acerbi described golden-berried material in Castelli Romani in 1825.|Acerbi 于1825年描述 Castelli Romani 的金色果粒材料。','Also called Rossetto; a distinct member of central Italy’s Trebbiano nomenclature.|亦称 Rossetto，是意大利中部 Trebbiano 名称体系中的独立品种。','Very vigorous, abundant fairly regular yields; medium-fertility soils without severe drought.|生长势很强、丰产且较稳定；宜中等肥力且不过分干旱的土壤。','Used in Lazio whites, including authorised secondary components in Frascati.|用于 Lazio 白酒，包括 Frascati 允许的辅助葡萄。','Yellow colour, delicate fragrance and a harmonious savoury palate.|黄色、香气细致，口感协调鲜美。','Rossetto identifies this grape; Trebbiano Toscano and Spoletino are separate.|Rossetto 指此品种，Trebbiano Toscano 与 Spoletino 另列。','Rossetto~Established synonym.|通用异名。','Good mildew tolerance but weaker tolerance to Botrytis.|对霜霉和白粉病耐受良好，但对灰霉较弱。','Prefers medium expansion and medium-length pruning.|宜中等开展整形及中梢修剪。'),
('abbuoto','Abbuoto','red','Recorded at Fondi and in the Pontine area; identification with ancient Caecuban grapes is only a historical hypothesis.|记载于 Fondi 与 Pontine 地区，与古代 Caecuban 葡萄的对应仅为历史推测。','Historic Lazio red capable of structured wines and ageing.|Lazio 历史红葡萄，可酿结构型及可陈年酒款。','Moderate vigour and variable moderate crops; exposed foothills, short pruning.|生长势中等、产量适中但有波动；宜向阳山麓及短梢修剪。','Red vinification; ageing is possible although colour can decline.|红酒酿造，可陈年但颜色可能减退。','Amaranth red, full-bodied and structured.|苋红色、酒体饱满且有结构。','Ancient Cecubo references cannot prove the identity of modern Abbuoto.|古代 Cecubo 记载不能证明现代 Abbuoto 身份。','','Good powdery mildew tolerance; vulnerable to late spring frost.|对白粉病耐受良好，易受晚春霜害。','Medium-large berries, firm purple-black skins, nearly colourless juice.|果粒中大、皮坚实紫黑，果汁近乎无色。')]
for a in lazio:
 id,name,c,origin,summ,vit,vin,taste,similar,aliases,e1,e2=a
 grape(id,name,c,'Lazio',origin,summ,vit,vin,taste,similar,aliases,urls=[L],extra=[('viticulture','Adaptation|适应性',e1,0),('viticulture','Morphology and registration|形态与登记',e2,0)])
save()
grape('malvasia-bianca-di-candia','Malvasia Bianca di Candia','white','Lazio','Long established in Lazio and Campania; the conventional Greek-origin narrative does not establish a precise pedigree.|长期分布于 Lazio 与 Campania；传统希腊起源说不能确定具体谱系。','A productive, mildly aromatic white and principal component of Frascati blends.|高产、轻芳香白葡萄，是 Frascati 混酿主要组分。','Mid-late budbreak, medium maturity; consistent high yield, moderate vigour and good drought tolerance.|萌芽中晚、成熟中等；高产稳定、生长势中等、耐旱良好。','Commonly blended; medium-long pruning and broad adaptability make it commercially useful.|常用于混酿；中长梢修剪及广适应性有利于生产。','Deep straw, discreet fragrance, savoury and mildly bitter finish.|深稻草色、香气含蓄、鲜美并略带苦味。','Distinct from Malvasia di Candia Aromatica and Malvasia del Lazio.|不同于 Malvasia di Candia Aromatica 及 Malvasia del Lazio。',extra=[('viticulture','Berries|果粒','Large, winged, relatively loose bunches; thin but firm golden-yellow skins.|果串大、带翼且相对疏松；金黄果皮薄但坚实。',0),('viticulture','Climate|气候','Adapts to many soil types when conditions are warm; tolerates winter cold and late frost reasonably well.|温暖条件下可适应多类土壤；对冬季低温及晚霜有较好耐性。',0)])
grape('nero-buono','Nero Buono','red','Lazio','Centred on Cori in Latina; documented in the 1883 agricultural inquiry.|集中于 Latina 的 Cori，1883年农业调查有记载。','A deeply coloured Lazio red central to Cori wines.|深色 Lazio 红葡萄，是 Cori 酒的重要基础。','Medium-high vigour, fairly high regular yields; expanded systems and medium-long pruning.|生长势中高、产量较高稳定；宜开展整形及中长梢修剪。','Varietal Cori Nero Buono and regional red blends.|用于 Cori Nero Buono 单品种及地方红酒混酿。','Intense red, good alcohol, vinous aroma and harmonious palate.|红色浓郁，酒精度良好，葡萄酒香明确、口感协调。','Nero Buono di Cori is a geographical extension of the grape name, not a different variety.|Nero Buono di Cori 是带地名的名称，并非另一品种。','Nero Buono di Cori~Qualified local name.|带地名的地方名称。',urls=[L],extra=[('viticulture','Rot|腐烂','Compact to very compact bunches can suffer sour rot in wet years.|紧密至极紧密果串在多雨年份可受酸腐病影响。',0),('viticulture','Skin|果皮','Medium-thick blue-black skin; firm pulp.|果皮中厚、蓝黑，果肉较结实。',0)])
grape('trebbiano-spoletino','Trebbiano Spoletino','white','Umbria','Traditional grape of the Spoleto valley and Montefalco; documented by Francolini in 1908.|Spoleto 谷地及 Montefalco 传统葡萄，Francolini 于1908年记载。','Distinct high-acid Umbrian white with late ripening and broad stylistic range.|独立的翁布里亚高酸白葡萄，成熟晚、酿造风格广。','Vigorous with tough skins; harvest from late September through October, sometimes early November.|生长势强、皮坚韧；采收从9月底延至10月，有时至11月初。','Still, sparkling, passito and skin-contact interpretations occur; acidity supports ageing.|可酿静态、起泡、风干甜及浸皮风格；酸度支持陈年。','Citrus-driven acidity, ripe fruit and volume; more balsamic nuances develop with style and maturity.|柑橘型酸度、成熟果味及饱满度；酿法与熟成可带出芳香草本层次。','Trebbiano Toscano is distinct. Historical Spoleto wines cannot automatically be assigned to today’s grape.|Trebbiano Toscano 不同；古代 Spoleto 酒不能自动对应现代此品种。',urls=[M],extra=[('viticulture','Training heritage|整形传统','Old vines survive trained to maple, elm and ash; modern hill plantings use trellises.|老藤仍可见攀附枫、榆、梣树，现代丘陵多采用棚架行栽。',0),('viticulture','Topography|地形','Cool humid plain sites may ripen later than better-exposed slopes.|凉湿平原地块可能较向阳坡地更晚成熟。',0)])
grape('incrocio-bruni-54','Incrocio Bruni 54','white','Marche','Bred by Bruno Bruni in Marche during his 1930s crossing programme.|Bruno Bruni 于1930年代在 Marche 的杂交计划中育成。','A vinifera cross combining floral-herbal aromas with the structure associated with Verdicchio.|欧洲种杂交，结合花草香及 Verdicchio 相关的结构表现。','Terra Argillosa harvests it before its other grapes, often in late August; this is a site observation.|Terra Argillosa 常于8月下旬、早于其其他品种采收；这是具体地块观察。','A Ida is gently pressed, fermented in steel and held on fine lees for several months.|A Ida 采用轻柔压榨、不锈钢发酵并在细酒泥上熟成数月。','Fresh, fragrant white style with pronounced floral-fruit aromas.|清新芬芳白酒风格，花果香突出。','An intraspecific Vitis vinifera crossing, not an interspecific hybrid.|为 Vitis vinifera 种内杂交，并非种间杂交。','Bruni 54~Short form.|简称。',urls=['https://terrargillosa.com/product/a-ida-marche-incrocio-bruni-54-igt/','https://terracruda.it/prodotto/incrocio-bruni-54-marche-igt-incrocio-bruni/'],parents=('bred-cross',['Sauvignon Blanc','Verdicchio'],'Sauvignon Blanc × Verdicchio, deliberate crossing by Bruno Bruni.|Sauvignon Blanc × Verdicchio，Bruno Bruni 人工杂交。'),extra=[('parentage','Parents|亲本','Sauvignon Blanc × Verdicchio.|Sauvignon Blanc × Verdicchio。',0),('vinification','Harvest handling|采收处理','Terra Argillosa harvests during cool hours and chills fruit on arrival.|Terra Argillosa 在较凉时段采收，并在入厂后冷却果实。',0)])
grape('grero','Grero','red','Umbria','Rare Umbrian grape recovered near Todi; nineteenth-century documentation and national registration in 2011.|Todi 附近恢复的稀有翁布里亚葡萄；十九世纪有文献，2011年国家登记。','A conservation success now returning to varietal red production.|经保育后重新用于单品种红酒。','Bettalunga observes relatively loose bunches, thick skins and useful disease tolerance.|Bettalunga 观察其果串较松、皮厚且耐病性有利。','Bettalunga regrafted vines in 2019 and harvested the renewed Grero plot in 2020.|Bettalunga 于2019年换接，2020年获得恢复地块的首批收成。','The estate reports high polyphenols with comparatively supple early tannins.|酒庄记录其多酚高、年轻单宁相对柔顺。','The local Greco Nero name should not merge this Todi material with all southern Italian Greco Nero records.|地方 Greco Nero 名称不能把 Todi 材料与南意大利所有同名品种合并。',urls=['https://www.bettalunga.it/en/the-vineyard/'],extra=[('origin','Recovery|恢复','A surviving old mother vine was identified in Todi in 2009.|2009年在 Todi 发现存活的古老母株。',0),('viticulture','Estate site|酒庄地块','Bettalunga’s plot is at 250 m, with clay, pebbles and sandy veins in heterogeneous hill soils.|Bettalunga 地块海拔250米，丘陵土含黏土、卵石及砂层。',0)])
grape('garofanata','Garofanata','white','Marche','Marche variety recorded by AMAP in Ancona and Macerata and conserved at Petritoli.|AMAP 记录其分布于 Ancona 与 Macerata，并在 Petritoli 保存。','Rare local white variety, also called Garofalata, revived in modern varietal bottlings.|稀有地方白葡萄，亦称 Garofalata，现重新用于单品种装瓶。','Preserved in the regional grape germplasm collection; cultivation and selection underpin its recovery.|保存于地区葡萄种质资源圃，栽培与选择是恢复基础。','Terracruda produces a varietal Marche IGT white called Innominata.|Terracruda 将其酿成名为 Innominata 的 Marche IGT 单品种白酒。','Fresh white profile with floral and fruit aromas; producer-specific style varies.|清新白酒风格、花果香；具体表现随酒庄酿法变化。','Historical descriptions linking it to Moscato do not establish synonymy or a complete pedigree.|历史上与 Moscato 相联系的描述不能确定异名或完整谱系。','Garofalata~AMAP synonym.|AMAP 收录异名。',urls=['https://www.amap.marche.it/files/progetti/biodiversita_agraria/repertorio_regionale/42-Garofanata.pdf','https://terracruda.it/prodotto/innominata-marche-igt-bianco/'],extra=[('origin','Conservation|保育','Entered the regional repertoire on 6 December 2007 as resource 42.|2007年12月6日进入地区资源名录，编号42。',0),('vinification','Reference wine|代表酒','Innominata demonstrates a varietal wine under Marche IGT.|Innominata 展示 Marche IGT 下的单品种酿造。',1)])
grape('barsaglina','Barsaglina','red','Toscana','Associated with Massa-Carrara; documented in 1874 with the synonym Massaretta.|与 Massa-Carrara 有关，1874年已记录 Massaretta 异名。','A deeply coloured, phenolic Tuscan red useful both alone and in Sangiovese blends.|深色、高酚托斯卡纳红葡萄，可单酿或与 Sangiovese 混酿。','Vigorous with low bud fertility; budbreak similar to Sangiovese, ripening often 7–10 days earlier.|生长势强、芽眼结实率低；萌芽近 Sangiovese，成熟常早7至10天。','Adds colour and freshness to blends; varietal trials give substantial reds.|为混酿增加颜色与清新度，单酿试验得到结构型红酒。','Deep ruby, full palate, fresh vegetal notes and potentially firm tannin.|深宝石红、口感饱满，清新植物气息及可能较强的单宁。','Massaretta is the synonym supported by the University of Pisa’s VitisDB record.|Massaretta 为比萨大学 VitisDB 支持的异名。','Massaretta~Massa-Carrara synonym.|Massa-Carrara 异名。',urls=['https://vitisdb.it/varieties/show/986'],extra=[('viticulture','Sensitivity|敏感性','Spring frost can be damaging; powdery mildew is a particular susceptibility.|春霜可能造成严重损害，尤其易受白粉病影响。',0),('viticulture','Phenolics|酚类','High anthocyanin and total polyphenol levels are reported.|研究记录较高花色苷及总多酚。',0)])
grape('vermentino-nero','Vermentino Nero','red','Toscana','Northern Tuscan red cultivated around Fosdinovo and Carrara.|托斯卡纳北部红葡萄，栽培于 Fosdinovo 及 Carrara 周边。','A local red variety represented by Terenzuola’s Toscana IGT bottling.|地方红葡萄，Terenzuola 的 Toscana IGT 酒为实证。','Terenzuola uses Guyot and hand harvests parcels separately in the second half of September.|Terenzuola 采用 Guyot，在9月下半月按地块成熟度分别手工采收。','The estate ferments in concrete with manual punch-downs and ages on fine lees in concrete.|酒庄在混凝土中发酵、人工压帽，并在混凝土中酒泥熟成。','The documented wine is a dry red; its tasting profile is a blend expression, including 5% Pollera.|已记录酒款为干红，其品鉴表现属于包含5% Pollera 的混酿。','A shared name with white Vermentino is not sufficient evidence for a colour-mutation claim.|与白色 Vermentino 共名不足以证明颜色突变关系。',urls=['https://www.terenzuola.it/portfolio_page/vermentino-nero/'],extra=[('vinification','Composition|配方','Terenzuola’s reference wine contains 95% Vermentino Nero and 5% Pollera.|Terenzuola 代表酒为95% Vermentino Nero 与5% Pollera。',0),('viticulture','Site practice|地块实践','Estate densities are 8,000–11,000 vines/ha with yield at or below 1.2 kg/vine.|酒庄密度为每公顷8,000至11,000株，每株产量不超过1.2公斤。',0)])
grape('pollera-nera','Pollera Nera','red','Toscana','Local red of Lunigiana and the Colli di Luni area.|Lunigiana 与 Colli di Luni 地方红葡萄。','Traditional blending grape providing freshness in local reds.|当地传统混酿葡萄，贡献清新度。','Documented in coastal hill vineyards on the Ligurian–Tuscan border; general phenology needs further verification.|实际见于 Liguria–Toscana 边界沿海丘陵；普遍物候仍待进一步核实。','Lunae’s Niccolò V blends Pollera Nera with Sangiovese and Merlot, then matures in large oak.|Lunae 的 Niccolò V 将其与 Sangiovese、Merlot 混酿，再用大橡木桶熟成。','Lunae attributes freshness specifically to Pollera; the whole wine’s fruit and oak notes are not varietal diagnostic markers.|Lunae 特别将清新度归于 Pollera；整酒果香与木香不能视为品种诊断特征。','Pollera is the shortened local name; wine-blend descriptions should not be treated as isolated varietal trials.|Pollera 为地方简称；混酿描述不能当作单品种试验。','Pollera~Short local name.|地方简称。',urls=['https://www.cantinelunae.com/nicolo-v/'],extra=[('vinification','Reference maturation|代表酒熟成','Niccolò V spends 12 months in 20–30 hl oak and six months in bottle.|Niccolò V 在20至30百升橡木桶12个月，瓶陈6个月。',0),('vinification','Maceration|浸渍','The estate reports 12 days on skins for this blend.|酒庄记录该混酿浸皮12日。',0)])
