new={g['id']:g for g in D['grapes']};trans={t['id']:t for t in D['translations']};updates={u['id']:u for u in D['existingUpdates']}
for r in D['regions']:
 for edge in r['grapes']:
  gid=edge['grapeId'];role=edge['role'];ss={s['id']:s for s in r['sources']}
  if gid in new:
   if not any(x['name']==r['name'] for x in new[gid]['regions']):
    new[gid]['regions'].append({'name':r['name'],'country':'Italy','note':role['zh']});trans[gid]['regions'].append({'name':r['name'],'note':role['en']})
   for si in edge['sourceIds']:
    src=ss[si]
